export const approvalStatus = pgEnum('approval_status',
  ['pending','approved','denied','expired','consumed']);
export const approvalGrantScope = pgEnum('approval_grant_scope', ['call','tool']);

/** No foreign keys, denormalized display names — same rule as audit_event: the
 *  queue must survive the revocation of the key that filled it.
 *  NO raw-arguments column, by design. See args_preview. */
export const approvalRequest = pgTable('approval_request', {
  id:            uuid().defaultRandom().primaryKey(),
  createdAt:     timestamp({ withTimezone: true, precision: 3 }).notNull().defaultNow(),
  // pending  -> deadline to DECIDE   (createdAt + guardrails.approvalTtlMs, 15m)
  // approved -> deadline to CONSUME  (decidedAt + guardrails.ticketTtlMs,  10m)
  expiresAt:     timestamp({ withTimezone: true, precision: 3 }).notNull(),
  status:        approvalStatus().notNull().default('pending'),
  grantScope:    approvalGrantScope().notNull().default('call'),

  // requester
  principalKind: principalKind().notNull(),      // 'user' | 'apiKey' | 'oauth'
  principalId:   text().notNull(),               // user id, or better-auth apiKey id
  principalName: text().notNull(),               // captured at request time
  sourceIp:      inet(),

  // target
  serverId:      uuid().notNull(),
  serverSlug:    text().notNull(),
  toolName:      text().notNull(),               // BARE upstream name
  exposedName:   text().notNull(),               // what the caller actually sent
  groupSlug:     text(),

  // decision material
  callHash:      char({ length: 32 }).notNull(), // sha256(canonical {s,t,a})[0:32]
  argsPreview:   jsonb().$type<ArgsPreview>().notNull(),   // REDACTED projection only
  argsBytes:     integer().notNull(),
  reason:        text().notNull(),               // policy reason | 'secret_egress'
  ruleId:        text(),                         // opaque id from the policy engine
  secretHits:    jsonb().$type<Omit<SecretHit,'value'>[]>(),  // ids/labels/paths, never values

  // correlation + liveness
  requestId:     text().notNull(),
  traceId:       text(),
  waiters:       integer().notNull().default(1), // identical calls that joined this card
  held:          boolean().notNull().default(true),

  // outcome
  decidedAt:     timestamp({ withTimezone: true, precision: 3 }),
  decidedBy:     text(),                         // USER id — never an apiKey id
  decidedByName: text(),
  decisionNote:  text(),
  selfApproved:  boolean(),
  useCount:      integer().notNull().default(0), // tool-scope window grants
  consumedAt:    timestamp({ withTimezone: true, precision: 3 }),
  consumedRequestId: text(),
}, (t) => [
  // one card per identical in-flight call — this is the dedup that kills flooding
  uniqueIndex('approval_pending_uq').on(t.principalId, t.callHash)
    .where(sql`status = 'pending'`),
  index('approval_queue_idx').on(t.status, t.createdAt.desc()),
  index('approval_ticket_idx').on(t.principalId, t.serverId, t.toolName)
    .where(sql`status = 'approved'`),
  check('approval_preview_len', sql`pg_column_size(args_preview) <= 8192`),
  check('approval_note_len',    sql`decision_note IS NULL OR length(decision_note) <= 280`),
  check('approval_human_only',  sql`decided_by IS NULL OR decided_at IS NOT NULL`),
]);

// -- ticket consumption: two plain statements, single-use enforced in SQL ------
// (1) call-scope, single use — run FIRST so an explicit one-off burns before a window
UPDATE approval_request SET status='consumed', consumed_at=now(), consumed_request_id=$req
 WHERE id = (SELECT id FROM approval_request
              WHERE status='approved' AND grant_scope='call' AND expires_at > now()
                AND principal_id=$pid AND call_hash=$hash
              LIMIT 1 FOR UPDATE SKIP LOCKED)
 RETURNING *;
// (2) tool-scope window — reusable until expires_at, never 'consumed'
UPDATE approval_request SET use_count = use_count + 1
 WHERE status='approved' AND grant_scope='tool' AND expires_at > now()
   AND principal_id=$pid AND server_id=$sid AND tool_name=$tool
 RETURNING *;

// -- sweep, every 30 s -----------------------------------------------------
UPDATE approval_request SET status='expired'
 WHERE status IN ('pending','approved') AND expires_at < now() RETURNING id, status, waiters;
// -> audit approval.expired per row; SSE {t:'approval', op:'expired'}

// -- ArgsPreview: the only argument representation that is ever persisted ---
export type ArgsPreview = {
  v: 1;
  leaves: Array<{
    path: string;                                   // RFC 6901 JSON pointer
    type: 'string'|'number'|'boolean'|'null'|'array'|'object';
    value?: string | number | boolean | null;       // omitted when redacted
    redacted?: 'secret' | 'size';
    label?: string;                                 // secret LABEL, e.g. 'github.PAT'
    len?: number;
  }>;
  foldedLeaves?: number;                            // beyond the 64-leaf cap
};
// Rules: string leaf > 256 chars -> first 120 + len, redacted:'size'.
//        leaf hit by findManagedSecrets -> redacted:'secret' + label, value dropped.
//        > 64 leaves -> fold. Hard 8 KB via the DB CHECK, not a hope.

// The ONE escape hatch for an egress false positive. Named directly in the
// block message so the fix is a single click from the error.
ALTER TABLE secrets ADD COLUMN scan_egress boolean NOT NULL DEFAULT true;

// Drizzle:  scanEgress: boolean().notNull().default(true),
// Surfaced on the server edit screen as a per-value checkbox:
//   [x] block this value from leaving as a tool argument
// Flipping it writes a config-change audit_event like any other setting.

export type GuardrailReason =
  | 'policy_deny' | 'approval_pending' | 'approval_denied' | 'approval_timeout'
  | 'approval_queue_full' | 'approval_cooldown' | 'secret_egress' | 'guardrail_unavailable';

export type GuardrailMeta = {
  v: 1;
  reason: GuardrailReason;
  approvalId?: string;
  retryAfterMs?: number;
  /** present only for secret_egress: ids + labels + JSON pointers, NEVER values */
  secretHits?: Array<{ secretId: string; label: string; path: string; encoding: string }>;
};

/** HTTP 200 + isError result, NOT a JSON-RPC error: a thrown error makes most
 *  hosts abort the turn, which is the failure we are trying to avoid. */
export function guardrailDeny(m: GuardrailMeta, note?: string): CallToolResult {
  return { isError: true, content: [{ type: 'text', text: TEXT[m.reason](m, note) }],
           _meta: { 'io.mcprouter/guardrail': m } };
}

const TEXT: Record<GuardrailReason, (m: GuardrailMeta, n?: string) => string> = {
  policy_deny:        ()  => `Blocked by MCPRouter policy.`,
  approval_pending:   (m) => `Blocked pending operator approval (request ${m.approvalId}). `
                           + `No decision within 300s. Ask the user to approve it in the `
                           + `MCPRouter console, then call this tool again with identical arguments.`,
  approval_timeout:   (m) => TEXT.approval_pending(m),
  approval_denied:    (_, n) => `An operator denied this call${n ? `: ${n}` : '.'} Do not retry.`,
  approval_queue_full:(m) => `Blocked: too many of your calls are already awaiting approval. `
                           + `Retry after ${Math.ceil((m.retryAfterMs ?? 0)/1000)}s.`,
  approval_cooldown:  (m) => TEXT.approval_queue_full(m),
  secret_egress:      (m) => `Blocked: argument ${m.secretHits?.[0]?.path} contains a credential `
                           + `MCPRouter manages (${m.secretHits?.[0]?.label}). Nothing was sent upstream.`,
  guardrail_unavailable: () => `Blocked: MCPRouter could not evaluate its guardrails. Nothing was sent upstream.`,
};

// Sixth frame on the ONE channel. topics=approval. Delivered ONLY to sessions
// whose role is operator|admin — filtered server-side in the /api/events handler,
// never by the client.
export type ApprovalFrame = {
  t: 'approval';
  op: 'new' | 'decided' | 'expired';
  id: string;
  status: 'pending' | 'approved' | 'denied' | 'expired';
  pending: number;                 // current global pending count -> sidebar badge
  // 'new' only — enough to render the card HEAD without a fetch, and no more:
  server?: string; tool?: string; principal?: string; reason?: string;
  createdAt?: string; expiresAt?: string;
};

// CACHE RULE (both settled rules apply, in this order):
//   1. setQueryData(['approvals','count'], f.pending)     <- the `status` PATCH rule
//   2. invalidateQueries({ queryKey: ['approvals'],       <- the `changed` rule
//                          refetchType: 'active' })
// The badge updates on every screen; the list refetches only where it is mounted.

// The frame NEVER carries argsPreview, secretHits or any argument material.
// Card bodies arrive only over the authenticated REST fetch, so argument data
// never rides a long-lived broadcast stream.

export type Provenance = {
  v: 1; untrusted: true; source: 'upstream';
  server: string; tool: string; exposedName: string;
  requestId: string; receivedAt: string;        // ISO 8601
  bytes: number; blocks: number;
  envelopeId?: string;                          // present iff wrapped
  truncatedBytes?: number;
  links: { total: number; distinct: number; oddSchemes: boolean };
};

/** Order is load-bearing: inspect -> truncate -> wrap -> append the marker. */
export function label(r: CallToolResult, p: Provenance, mode: 'meta'|'meta+wrap'): CallToolResult {
  const out = { ...r, _meta: { ...r._meta, 'io.mcprouter/provenance': p } };
  if (mode === 'meta') return out;
  const n = base32(randomBytes(14));                     // 110 bits, 22 chars, fresh per result
  p.envelopeId = n;
  out.content = [
    { type: 'text', text: `⟦mcprouter:untrusted v=1 id=${n} src=${p.exposedName}⟧` },
    ...r.content,                                        // upstream blocks BYTE-IDENTICAL
    { type: 'text', text: `⟦/mcprouter:untrusted id=${n}⟧` },
  ];
  if (p.truncatedBytes)                                  // gateway text -> OUTSIDE the envelope
    out.content.push({ type: 'text', text: `[mcprouter:truncated ${p.truncatedBytes} bytes]` });
  return out;
}

// Truncation budget: the settled 1 MB ceiling is measured on the SERIALIZED UPSTREAM
// content before wrapping; 512 B is reserved for the two envelope blocks plus the
// truncation block. Truncation cuts the LAST text block at a UTF-8 code point boundary.
//
// Why the nonce: without it, upstream content emits `⟦/mcprouter:untrusted⟧` and escapes
// the envelope. With it, forgery requires guessing 110 bits the upstream never sees.
// Why ⟦⟧ (U+27E6/27E7): ASCII brackets are common in real tool output.
// Why no upstream block is modified: a client that JSON.parses content[0] must keep working
// when the envelope is off, and re-encoding upstream bytes would break resource/image blocks.
//
// HONESTY: this only helps clients that CHOOSE to honour it. No client honours it today.
// It is a labelling primitive so a host CAN distinguish our text from upstream text.
// It is not a defence against prompt injection and we do not describe it as one.

// packages/core/src/secrets/resolver.ts — the module that ALREADY caches resolved
// plaintext for connect. Plaintext never leaves it; the only export is the predicate.

export type SecretHit = {
  secretId: string;
  label: string;                               // 'github.GITHUB_TOKEN' — never the value
  encoding: 'literal' | 'base64' | 'urlencoded';
  path: string;                                // RFC 6901 pointer into the arguments
};

const MIN_LEN = 16;
let matcher: { re: RegExp; map: Map<string, { id: string; label: string; enc: SecretHit['encoding'] }> } | null = null;

/** Called wherever the resolved-config cache is invalidated (boot, server edit,
 *  secret rotation). One compiled alternation of ESCAPED LITERALS — this is a
 *  multi-string matcher, not a pattern heuristic. */
export function rebuildSecretMatcher(vals: Array<{ id: string; label: string; value: string; scanEgress: boolean }>) {
  const map = new Map<string, { id: string; label: string; enc: SecretHit['encoding'] }>();
  for (const v of vals) {
    if (!v.scanEgress || v.value.length < MIN_LEN) continue;
    const forms = [
      ['literal', v.value],
      ['base64', Buffer.from(v.value, 'utf8').toString('base64').replace(/=+$/, '')],
      ['urlencoded', encodeURIComponent(v.value)],
    ] as const;
    for (const [enc, s] of forms)
      if (s.length >= MIN_LEN && !map.has(s)) map.set(s, { id: v.id, label: v.label, enc });
  }
  const keys = [...map.keys()].sort((a, b) => b.length - a.length);   // longest alternative wins
  matcher = keys.length ? { re: new RegExp(keys.map(esc).join('|'), 'g'), map } : null;
}
const esc = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');   // RegExp.escape on Node 24+

export function findManagedSecrets(args: unknown): SecretHit[] {
  if (!matcher) return [];
  const hits: SecretHit[] = [];
  walkStrings(args, '', 16, 4096, (path, leaf) => {      // depth <= 16, <= 4096 leaves
    for (const m of leaf.matchAll(matcher!.re)) {
      const e = matcher!.map.get(m[0])!;
      if (!hits.some(h => h.secretId === e.id && h.path === path))
        hits.push({ secretId: e.id, label: e.label, encoding: e.enc, path });
    }
  });
  return hits;
}

// WHY THIS IS NOT THEATRE: a hit means the argument literally contains a credential
// we manage. There is no false-confidence class — only the honest false positive of
// "the caller really did mean to send that value", which `secrets.scan_egress = false`
// resolves in one click, named in the block message.
//
// WE REFUSE the generic version: no PII regex, no entropy-based secret detection, no
// "looks like an AWS key" patterns. Those have the exact false-confidence profile we
// already rejected for audit redaction, and an operator who trusts them is worse off.
//
// ponytail: leaf-only, single-encoding, >=16 chars. Misses a secret split across two
// arguments or double-encoded. Upgrade path if it matters: hash every L-length window
// per distinct secret length instead of one alternation — ~20x slower, catches slicing.
//
// Cost: one compiled alternation over each string leaf; ~1 MB of arguments is single-
// digit milliseconds in V8. Results are NOT scanned: a secret echoed back by an upstream
// is caught at the next hop, where it would become an argument.

export type ResultShape = {
  bytes: number;
  blocks: number;
  links: { total: number; distinct: number; oddSchemes: boolean; hosts: string[] };
  mimeTypes: string[];                 // declared on image/audio/resource blocks
  truncatedBytes?: number;
};

const URL_RE = /\b[a-z][a-z0-9+.-]*:\/\/[^\s<>"')\]]+/gi;

export function inspectResult(r: CallToolResult): ResultShape { /* first 256 KB of text
  blocks + every resource.uri; oddSchemes = any scheme not in {http, https};
  hosts capped at 10, sorted, audit-only. */ }

// BLOCK (three, all defended):
//   1. managed-secret hit in ARGUMENTS      — GB-D8. Literal match, loud, one-click fix.
//   2. 1 MB result ceiling                  — already settled; a truncation, not a refusal.
//   3. malformed result                     — FREE: client.callTool already parses with the
//      SDK's CallToolResultSchema, so a protocol-violating upstream throws before we see it.
//      Rung 3 of the ladder: the SDK does it, we add nothing.
//
// REPORT (everything else):
//   link counts, distinct hosts, odd URL schemes (data:/file:/javascript:), declared mime
//   types, block count, byte size. Into _meta.provenance, into audit_event.result_shape,
//   and into two counters:
//     mcpr_result_links_total{server}        mcpr_result_odd_scheme_total{server}
//   NEVER labelled by host or tool on a histogram — the settled cardinality rule.
//
// THEATRE, explicitly refused:
//   · regex / heuristic prompt-injection detection on results — same false confidence as
//     the regex redactor we already rejected, and a gateway cannot control how the
//     client's model frames what it receives.
//   · "sanitizing" results by stripping instruction-like text — breaks legitimate output
//     and stops nothing determined.
//   · generic PII or secret-shape regexes on arguments — see GB-D8.
//   · claiming the provenance label defends against injection — it labels, nothing more.
